/// Type `t`'s node, as an operand.
pub fn rx_ty(mut s: &'static St, mut x: &'static Rx, mut sc: Rpbinds, mut t: &'static Ty) -> &'static Rxa {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyVar(n) => {
                return rx_var(x, sc, n);
            }
            Ty::TyMeta(k) => {
                return rxa(rx_declined(x, str_lit("a type not solved")), rx_sym(str_lit("?")));
            }
            Ty::TyData(d, args) => {
                if has_prefix_p(d, str_lit("%named ")) {
                    t = car(args);
                    continue;
                } else if (null_p(args) && not(null_p(scope_var(sc, d)))) {
                    // A module type's abstract type, bound by its `moduleof`.
                    return rx_var(x, sc, d);
                } else {
                    let tagcase_ = rx_reserve(x);
                    match *tagcase_ {
                        Rxi::Rxi(x, slot) => {
                            return rxa(rx_ty_at(s, x, sc, walk(s, t), slot), the::<RpOperand>(kayak_rt::heap_alloc(Sum_4node_5bound_4hole_5const_3sym_3int_4flag::<Int, Product_11_12<Int, Int>, Int, Product_11_12_13<Str, Int, Str>, Symbol, Int, bool>::Node(i64_to_int(slot)))));
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                let tagcase_ = rx_reserve(x);
                match *tagcase_ {
                    Rxi::Rxi(x, slot) => {
                        return rxa(rx_ty_at(s, x, sc, other, slot), the::<RpOperand>(kayak_rt::heap_alloc(Sum_4node_5bound_4hole_5const_3sym_3int_4flag::<Int, Product_11_12<Int, Int>, Int, Product_11_12_13<Str, Int, Str>, Symbol, Int, bool>::Node(i64_to_int(slot)))));
                    }
                }
            }
        }
    }
}

